export const RED=new Set([1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36]);
export function rng(seed){let s=2166136261;for(const c of String(seed))s=Math.imul(s^c.charCodeAt(0),16777619);return()=>{s=(s+0x6D2B79F5)|0;let t=s;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return ((t^t>>>14)>>>0)/4294967296;};}
export function options(type,n){let a=[];const add=(v,label=v)=>a.push({value:String(v),label:String(label)});if(type==='straight'){for(let i=0;i<n;i++)add(i,i===37?'00':i===38?'000':i);}if(type==='dozen'||type==='column')for(let i=1;i<=3;i++)add(i,type==='dozen'?`${(i-1)*12+1}–${i*12}`:`Column ${i}`);if(type==='split'){for(let i=1;i<=36;i++){if(i%3!==0)add(`${i},${i+1}`);if(i<=33)add(`${i},${i+3}`);}}if(type==='street')for(let i=1;i<=34;i+=3)add(`${i},${i+1},${i+2}`);if(type==='corner')for(let i=1;i<=32;i++){if(i%3!==0)add(`${i},${i+1},${i+3},${i+4}`);}if(type==='six')for(let i=1;i<=31;i+=3)add(Array.from({length:6},(_,j)=>i+j).join(','));return a;}
export function numbers(b,n){switch(b.type){case 'red':return [...RED];case 'black':return Array.from({length:36},(_,i)=>i+1).filter(x=>!RED.has(x));case 'odd':return Array.from({length:18},(_,i)=>i*2+1);case 'even':return Array.from({length:18},(_,i)=>i*2+2);case 'low':return Array.from({length:18},(_,i)=>i+1);case 'high':return Array.from({length:18},(_,i)=>i+19);case 'dozen':return Array.from({length:12},(_,i)=>(+b.value-1)*12+i+1);case 'column':return Array.from({length:12},(_,i)=>i*3+(+b.value));case 'basket':return [0,37,1,2,3];default:return String(b.value).split(',').map(Number);}}
export function prepare(b,n){const nums=numbers(b,n);return {...b,nums,payout:b.type==='basket'?6:36/nums.length-1,edge:b.type==='basket'?3/38:(n-36)/n};}
export function settle(b,pocket,stake){return b.nums.includes(pocket)?stake*b.payout:-stake;}
export function describeBet(b,n){const prepared=prepare(b,n),display=x=>x===37?'00':x===38?'000':String(x);const outside={red:'Red',black:'Black',odd:'Odd',even:'Even',low:'1–18',high:'19–36'};let label=outside[b.type];if(b.type==='straight')label=display(+b.value);if(b.type==='dozen')label=`Dozen ${b.value} (${prepared.nums[0]}–${prepared.nums.at(-1)})`;if(b.type==='column')label=`Column ${b.value}`;if(['split','street','corner','six','basket'].includes(b.type)){const name={split:'Split',street:'Street',corner:'Corner',six:'Six-line',basket:'Basket'}[b.type];label=`${name} ${prepared.nums.map(display).join(' / ')}`;}return {type:b.type,value:b.value??'',label,payout:prepared.payout,nums:prepared.nums};}
export function bettingCommand(target,{amount,every,start}){return `Place ¤${new Intl.NumberFormat('en',{maximumFractionDigits:2}).format(amount)} on ${target.label}, every ${every} spin${every===1?'':'s'}, starting on spin ${start}.`;}
export function multiplier(kind,index){if(kind==='martingale'||kind==='reverse')return 2**Math.min(index,1023);if(kind==='dalembert')return index+1;if(kind==='fibonacci'){let a=1,b=1;for(let i=0;i<Math.min(index,1500);i++){[a,b]=[b,a+b];}return a;}return 1;}
export function nextIndex(kind,index,net,reset=3){if(Math.abs(net)<1e-8)return index;if(kind==='martingale')return net>0?0:index+1;if(kind==='reverse')return net<0||index+1>=reset?0:index+1;if(kind==='fibonacci')return net>0?Math.max(0,index-2):index+1;if(kind==='dalembert')return net>0?Math.max(0,index-1):index+1;return 0;}
export function session(c,random,keepPath=false){const bets=c.bets.map(b=>prepare(b,c.pockets));let bank=c.bankroll,index=0,wagered=0,benchmark=0,spins=0,wageringSpins=0,limitHits=0,reason='spin limit',path=[{x:0,y:0}];const stride=Math.max(1,Math.floor(c.spins/150));
for(let i=0;i<c.spins;i++){if(c.takeProfit>0&&bank-c.bankroll>=c.takeProfit){reason='profit target';break;}if(c.stopLoss>0&&c.bankroll-bank>=c.stopLoss){reason='loss target';break;}const round=i+1,active=bets.filter(b=>round>=(b.start||1)&&(round-(b.start||1))%(b.every||1)===0);const pocket=Math.floor(random()*c.pockets);
if(active.length){const amounts=active.map(b=>b.amount??c.base*b.units),groups={};active.forEach((b,j)=>{const key=[...b.nums].sort((a,b)=>a-b).join(',');groups[key]=(groups[key]||0)+amounts[j];});let mult=multiplier(c.strategy,index);const maxMult=c.tableMax/Math.max(...Object.values(groups));if(mult>maxMult){limitHits++;if(c.limitRule==='stop'||(c.limitRule==='reset'&&maxMult<1)){reason='table limit';break;}if(c.limitRule==='reset'){index=0;mult=1;}else mult=maxMult;}const stakes=amounts.map(a=>a*mult),total=stakes.reduce((a,b)=>a+b,0);if(total>bank+1e-7){reason=bank<1e-7?'bankrupt':'cannot fund next bet';break;}let net=0;for(let j=0;j<active.length;j++){net+=settle(active[j],pocket,stakes[j]);benchmark-=stakes[j]*active[j].edge;}bank+=net;wagered+=total;wageringSpins++;index=nextIndex(c.strategy,index,net,c.resetWins);}
spins++;if(keepPath&&(spins%stride===0||spins===c.spins))path.push({x:spins,y:bank-c.bankroll});}
if(keepPath&&path.at(-1).x!==spins)path.push({x:spins,y:bank-c.bankroll});return {profit:bank-c.bankroll,bank,wagered,benchmark,spins,wageringSpins,reason,limitHits,path:keepPath?path:undefined};}
export function simulate(c,onProgress=()=>{}){const random=rng(c.seed),results=[];for(let i=0;i<c.sessions;i++){results.push(session(c,random,i<12));if(i%100===0)onProgress(i/c.sessions);}return results;}
